function plan(api) {
  const orientation = " Coordinate contract: Y+ is up, Z+ is the front/entrance/forward direction, X+ is right; place doors, facades, openings, windshields, or noses toward local Z+ and keep the model centered at its origin.";
  const initialSamples = [];
  for (let x = -36; x <= 36; x += 12) {
    for (let z = -36; z <= 36; z += 12) {
      const s = api.environmentSample([x, z]);
      initialSamples.push({ x: x, z: z, height: s.height, slope: s.slope });
    }
  }

  let xVariation = 0;
  let zVariation = 0;
  for (let t = -24; t <= 24; t += 12) {
    xVariation += Math.abs(api.environmentSample([-28, t]).height - api.environmentSample([28, t]).height);
    zVariation += Math.abs(api.environmentSample([t, -28]).height - api.environmentSample([t, 28]).height);
  }
  const rotate = xVariation < zVariation;
  function world(p) {
    return rotate ? [p[1], -p[0]] : [p[0], p[1]];
  }
  function distance(a, b) {
    const dx = a[0] - b[0];
    const dz = a[1] - b[1];
    return Math.sqrt(dx * dx + dz * dz);
  }
  function mix(a, b, t) {
    return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
  }
  function segmentDistance(p, a, b) {
    const dx = b[0] - a[0];
    const dz = b[1] - a[1];
    const d = dx * dx + dz * dz;
    const t = d > 0 ? Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / d)) : 0;
    return distance(p, mix(a, b, t));
  }
  function asset(key, name, prompt, dimensions, role, variants, light) {
    const spec = {
      key: key,
      name: name,
      prompt: prompt + orientation,
      dimensions: dimensions,
      role: role,
      variants: variants
    };
    if (light) spec.light = light;
    return api.requireAsset(spec);
  }

  api.sceneIntent({ kind: "authored", reason: "保留已有山谷地形，通过比较街巷网络组织层层叠落的密集石屋村庄。" });

  const nodes = [
    world([-20, -24]), world([0, -24]), world([20, -24]),
    world([-20, 0]), world([0, 0]), world([20, 0]),
    world([-20, 24]), world([0, 24]), world([20, 24]),
    world([-37, -24])
  ];
  const hubs = [1, 4, 7];
  const publicSites = [
    { p: world([0, -34]), hub: 1, key: "inn", name: "南院旅舍", width: 8, depth: 7 },
    { p: world([8, 9]), hub: 4, key: "hall", name: "村民议事堂", width: 7, depth: 6 },
    { p: world([0, 34]), hub: 7, key: "chapel", name: "山谷钟堂", width: 8, depth: 7 }
  ];
  const candidateEdges = [
    [[9, 0], [0, 1], [1, 2], [3, 4], [4, 5], [6, 7], [7, 8], [0, 3], [3, 6], [1, 4], [4, 7], [2, 5], [5, 8]],
    [[9, 0], [0, 1], [1, 2], [2, 5], [5, 4], [4, 3], [3, 6], [6, 7], [7, 8]]
  ];
  const baseHeights = [];
  for (const p of nodes) baseHeights.push(api.environmentSample(p).height);

  function evaluate(edges) {
    const heights = [];
    for (const h of baseHeights) heights.push(h);
    for (let pass = 0; pass < 32; pass++) {
      for (const edge of edges) {
        const a = edge[0], b = edge[1];
        const limit = distance(nodes[a], nodes[b]) * 0.095;
        const difference = heights[a] - heights[b];
        if (difference > limit) {
          const correction = (difference - limit) * 0.5;
          heights[a] -= correction;
          heights[b] += correction;
        } else if (difference < -limit) {
          const correction = (-difference - limit) * 0.5;
          heights[a] += correction;
          heights[b] -= correction;
        }
      }
    }
    let grading = 0;
    let slopeCost = 0;
    let length = 0;
    for (const edge of edges) {
      const a = nodes[edge[0]], b = nodes[edge[1]];
      const span = distance(a, b);
      length += span;
      for (let j = 0; j <= 8; j++) {
        const t = j / 8;
        const sample = api.environmentSample(mix(a, b, t));
        const target = heights[edge[0]] * (1 - t) + heights[edge[1]] * t;
        grading += Math.abs(sample.height - target) * span / 9;
        slopeCost += Math.abs(sample.slope) * span / 9;
      }
    }

    const parcels = [];
    for (let e = 0; e < edges.length; e++) {
      const edge = edges[e];
      if (edge[0] === 9 || edge[1] === 9) continue;
      const a = nodes[edge[0]], b = nodes[edge[1]];
      const span = distance(a, b);
      const dx = (b[0] - a[0]) / span, dz = (b[1] - a[1]) / span;
      for (let along = 5; along < span - 3; along += 8) {
        const t = along / span;
        const anchor = mix(a, b, t);
        for (const side of [-1, 1]) {
          const p = [anchor[0] - dz * 6.4 * side, anchor[1] + dx * 6.4 * side];
          let valid = Math.abs(p[0]) < 36 && Math.abs(p[1]) < 36;
          for (const hub of hubs) if (distance(p, nodes[hub]) < 8.7) valid = false;
          for (const site of publicSites) if (distance(p, site.p) < 9.5) valid = false;
          for (let other = 0; other < edges.length; other++) {
            if (other !== e && segmentDistance(p, nodes[edges[other][0]], nodes[edges[other][1]]) < 5.8) valid = false;
          }
          for (const q of parcels) if (distance(p, q.p) < 7.6) valid = false;
          if (!valid) continue;
          const target = heights[edge[0]] * (1 - t) + heights[edge[1]] * t;
          let low = 100, high = -100, earth = 0;
          for (const offset of [[0, 0], [-2.6, -3], [-2.6, 3], [2.6, -3], [2.6, 3]]) {
            const q = [
              p[0] + dx * offset[0] - dz * side * offset[1],
              p[1] + dz * offset[0] + dx * side * offset[1]
            ];
            const sample = api.environmentSample(q);
            low = Math.min(low, sample.height);
            high = Math.max(high, sample.height);
            earth += Math.abs(sample.height - target);
          }
          if (high - low > 6 || earth / 5 > 4) continue;
          parcels.push({ p: p, anchor: anchor, height: target, dx: dx, dz: dz, edge: e, earth: earth });
        }
      }
    }

    const paths = [];
    for (let i = 0; i < nodes.length; i++) {
      const row = [];
      for (let j = 0; j < nodes.length; j++) row.push(i === j ? 0 : 10000);
      paths.push(row);
    }
    for (const edge of edges) {
      const d = distance(nodes[edge[0]], nodes[edge[1]]);
      paths[edge[0]][edge[1]] = d;
      paths[edge[1]][edge[0]] = d;
    }
    for (let k = 0; k < nodes.length; k++) {
      for (let i = 0; i < nodes.length; i++) {
        for (let j = 0; j < nodes.length; j++) {
          paths[i][j] = Math.min(paths[i][j], paths[i][k] + paths[k][j]);
        }
      }
    }
    let walking = 0;
    for (let i = 0; i < 9; i++) {
      let nearest = 10000;
      for (const hub of hubs) nearest = Math.min(nearest, paths[i][hub]);
      walking += nearest + paths[i][4] * 0.25;
    }
    let footprintCost = 0;
    for (const parcel of parcels) footprintCost += parcel.earth / 5;
    return {
      edges: edges,
      heights: heights,
      parcels: parcels,
      score: grading * 1.8 + slopeCost * 0.15 + length * 0.3 + walking * 1.4 + footprintCost - parcels.length * 24
    };
  }

  const linkedLanes = evaluate(candidateEdges[0]);
  const contourSequence = evaluate(candidateEdges[1]);
  const chosen = linkedLanes.score <= contourSequence.score ? linkedLanes : contourSequence;

  const house = asset("stone-home", "山谷石屋", "Standalone compact inhabited vernacular mountain stone house, thick irregular masonry, two and three storey silhouette variants, slate gable roof, integrated chimney, recessed ground-floor front doorway flush with its base, wooden shutters, small upper balcony and attached window flower boxes. Weathered but maintained. No external stairs blocking the street, no ground, lettering or background.", [5.2, 7.2, 6], "structure", 3);
  const inn = asset("inn", "石屋旅舍", "Standalone mountain village stone inn, broad slate roof, two storeys, integrated sheltered front arcade with an open central entrance, timber upper gallery, visible simple tables inside arcade, chimney and unlettered hanging sign. Ground-level entrance, no surrounding ground or background.", [8, 8, 7], "structure", 1);
  const hall = asset("hall", "村民议事堂", "Standalone civic meeting hall in mountain village masonry, dignified but modest, tall central assembly room, slate roof, small roof lantern, broad ground-level front double entrance, deep stone window reveals and integrated carved lintel. No lettering, ground or background.", [7, 8.5, 6], "structure", 1);
  const chapel = asset("chapel", "山谷钟堂", "Standalone small stone village chapel and community bell house, narrow attached square bell tower, visible bronze bell in open belfry, slate roof, front arched ground-level entrance, modest carved stone details. No lettering, surrounding ground or background.", [8, 12, 7], "structure", 1);
  const stall = asset("market-stall", "山村摊位", "Standalone reusable small mountain market stall, timber frame, simple cloth canopy, integral counter displaying baskets of vegetables, bread and ceramic jars, open customer side faces front. No people, lettering, ground or background.", [2.5, 2.8, 1.7], "structure", 2);
  const bench = asset("bench", "石脚长椅", "Standalone village bench with heavy stone supports and worn timber seat and back, sitting direction toward front. No ground or background.", [2.1, 1, 0.65], "structure", 1);
  const well = asset("well", "村井", "Standalone communal mountain village well, circular waist-high stone parapet enclosing a visibly recessed dark shaft, timber crossbeam, winding wheel, rope and attached bucket, no ground or background.", [2.1, 3.1, 2.1], "structure", 1);
  const trough = asset("trough", "石槽水台", "Standalone carved stone village drinking trough with integrated upright spring spout and shallow contained water in the basin, no surrounding water, ground or background.", [2.1, 1.5, 0.9], "structure", 1);
  const cart = asset("cart", "山村手推车", "Standalone parked wooden two-wheel handcart carrying burlap sacks and wicker baskets, handles pointing forward, no ground or background.", [1.5, 1.4, 2.3], "structure", 1);
  const goods = asset("household-goods", "柴薪陶罐", "Standalone compact domestic storage grouping, neatly stacked split firewood under a low timber cover with two earthenware storage jars beside it. No surrounding ground or background.", [1.4, 1.3, 1.1], "structure", 2);
  const lamp = asset("village-lamp", "街巷灯柱", "Standalone slender wrought iron village lamp post, enclosed warm glass lantern at top, simple stone foot, functional light source inside lantern, no ground or background.", [0.5, 3.4, 0.5], "structure", 1, { kind: "point", color: "#FFD49A", intensity: 1.7, range: 7, offset: [0, 3, 0] });
  const tree = asset("valley-tree", "山谷乔木", "Standalone mature temperate mountain broadleaf tree with irregular branching, open lower trunk, asymmetrical natural crown, no ground or background.", [6, 10, 6], "environment", 2);
  const pine = asset("ridge-pine", "山坡松树", "Standalone mountain pine tree, rugged trunk, layered irregular needle branches and wind-shaped crown, no ground or background.", [5, 11, 5], "environment", 2);
  const rock = asset("valley-rock", "山坡岩石", "Standalone cluster of natural fractured mountain stones, varied angular faces, restrained patches of moss, no ground or background.", [3, 2, 2.5], "environment", 2);
  const shrub = asset("valley-shrub", "林缘灌木", "Standalone irregular temperate woodland shrub clump with fine branches and dense small leaves, no ground or background.", [2.2, 1.7, 2], "environment", 2);

  api.grass({
    id: "valley-groundcover",
    preset: "meadow",
    region: { kind: "polygon", points: [[-47, -47], [47, -47], [47, 47], [-47, 47]] },
    density: 0.5,
    variation: 0.55,
    height: 0.24,
    mix: { short: 0.65, tall: 0.28, flowers: 0.07 },
    seed: api.seed
  });

  for (let i = 0; i < nodes.length; i++) {
    api.sculptTerrain({ mode: "flatten", point: nodes[i], radius: 3.4, targetHeight: chosen.heights[i], strength: 1 });
  }
  for (const hub of hubs) {
    api.sculptTerrain({ mode: "flatten", point: nodes[hub], radius: 6.3, targetHeight: chosen.heights[hub], strength: 1 });
  }

  const routeIds = [];
  for (let i = 0; i < chosen.edges.length; i++) {
    const edge = chosen.edges[i];
    const a = nodes[edge[0]], b = nodes[edge[1]];
    const entry = edge[0] === 9;
    api.rampTerrain({
      start: a, end: b, width: 5.5,
      startHeight: chosen.heights[edge[0]],
      endHeight: chosen.heights[edge[1]],
      softness: 0.8, strength: 1
    });
    const id = api.route({
      id: "village-lane-" + i,
      name: entry ? "入谷村道" : "连通石巷",
      points: [a, b],
      curve: "polyline",
      width: entry ? 3.6 : 3.2,
      surface: "paving",
      material: "cobblestone",
      groupId: "village-circulation",
      guideRole: entry ? "entry" : "axis"
    });
    routeIds.push(id);
  }

  for (const hub of hubs) {
    api.surface({
      id: "public-court-" + hub,
      surface: "paving",
      material: "garden-stone",
      region: { kind: "circle", center: nodes[hub], radius: 5.8 },
      clearNatural: true
    });
  }

  const occupied = [];
  for (const parcel of chosen.parcels) {
    api.sculptTerrain({ mode: "flatten", point: parcel.p, radius: 4.4, targetHeight: parcel.height, strength: 1 });
  }
  for (const site of publicSites) {
    const h = chosen.heights[site.hub];
    api.sculptTerrain({ mode: "flatten", point: site.p, radius: 6, targetHeight: h, strength: 1 });
  }

  for (let i = 0; i < chosen.parcels.length; i++) {
    const parcel = chosen.parcels[i];
    const group = "home-court-" + i;
    const toward = [
      (parcel.anchor[0] - parcel.p[0]) / 6.4,
      (parcel.anchor[1] - parcel.p[1]) / 6.4
    ];
    const doorstep = [parcel.p[0] + toward[0] * 3.05, parcel.p[1] + toward[1] * 3.05];
    api.rampTerrain({
      start: parcel.anchor, end: doorstep, width: 1.8,
      startHeight: parcel.height, endHeight: parcel.height,
      softness: 0.5, strength: 1
    });
    api.surface({
      id: "house-pad-" + i,
      surface: "soil", material: "compacted-earth",
      region: { kind: "circle", center: parcel.p, radius: 4.2 },
      clearNatural: true
    });
    api.route({
      id: "house-access-" + i,
      name: "入户短巷",
      points: [parcel.anchor, doorstep],
      width: 1.35,
      surface: "paving",
      material: "garden-stone",
      groupId: group
    });
    api.place({
      assetId: api.asset(house, i % 3),
      name: "层叠石屋",
      position: parcel.p,
      facing: { target: parcel.anchor },
      groupId: group
    });
    const storage = [
      parcel.p[0] - toward[0] * 3.2 + parcel.dx * 1.35,
      parcel.p[1] - toward[1] * 3.2 + parcel.dz * 1.35
    ];
    api.place({ assetId: api.asset(goods, i % 2), position: storage, facing: { target: parcel.anchor }, groupId: group });
    if (i % 3 === 0) {
      const seat = [
        doorstep[0] + parcel.dx * 1.7,
        doorstep[1] + parcel.dz * 1.7
      ];
      api.place({ assetId: api.asset(bench, 0), position: seat, facing: { target: parcel.anchor }, groupId: group });
    }
    occupied.push({ p: parcel.p, radius: 5 });
  }

  for (let i = 0; i < publicSites.length; i++) {
    const site = publicSites[i];
    const hub = nodes[site.hub];
    const h = chosen.heights[site.hub];
    const group = "public-ensemble-" + i;
    const d = distance(site.p, hub);
    const forward = [(hub[0] - site.p[0]) / d, (hub[1] - site.p[1]) / d];
    const door = [site.p[0] + forward[0] * site.depth * 0.5, site.p[1] + forward[1] * site.depth * 0.5];
    api.rampTerrain({ start: hub, end: door, width: 3, startHeight: h, endHeight: h, softness: 0.6, strength: 1 });
    api.route({ id: "public-access-" + i, name: "公共建筑入口", points: [hub, door], width: 2.5, surface: "paving", material: "garden-stone", groupId: group });
    const family = site.key === "inn" ? inn : site.key === "hall" ? hall : chapel;
    api.place({ assetId: api.asset(family, 0), name: site.name, position: site.p, facing: { target: hub }, groupId: group });
    occupied.push({ p: site.p, radius: 6.5 });
    occupied.push({ p: hub, radius: 6.5 });

    const localHub = site.hub === 1 ? [0, -24] : site.hub === 4 ? [0, 0] : [0, 24];
    for (const offset of [[-3.7, 2.8], [3.7, -2.8]]) {
      const p = world([localHub[0] + offset[0], localHub[1] + offset[1]]);
      api.place({ assetId: api.asset(bench, 0), position: p, facing: { target: hub }, groupId: group });
    }
    for (const offset of [[-4, -3.5], [4, 3.5]]) {
      const p = world([localHub[0] + offset[0], localHub[1] + offset[1]]);
      api.place({ assetId: api.asset(lamp, 0), position: p, groupId: group });
    }
    const feature = world([localHub[0] - 3, localHub[1] - 2.2]);
    api.place({ assetId: api.asset(i === 1 ? well : trough, 0), position: feature, facing: { target: hub }, groupId: group });
    if (i === 0) {
      api.place({ assetId: api.asset(cart, 0), position: world([4.1, -31]), facing: { target: hub }, groupId: group });
      for (let j = 0; j < 2; j++) {
        api.place({ assetId: api.asset(goods, j), position: world([-4.8, -32.5 - j * 1.8]), facing: { target: hub }, groupId: group });
      }
    }
    if (i === 1) {
      for (let j = 0; j < 2; j++) {
        const p = world([-2.3 + j * 3.2, 4.4]);
        api.place({ assetId: api.asset(stall, j), position: p, facing: { target: hub }, groupId: group });
      }
    }
    if (i === 2) {
      for (let j = 0; j < 3; j++) {
        api.place({ assetId: api.asset(bench, 0), position: world([-3.4 + j * 3.4, 29]), facing: { target: site.p }, groupId: group });
      }
    }
  }

  for (let i = 0; i < routeIds.length; i++) {
    api.placeAlongRoute({
      routeId: routeIds[i],
      assetId: api.asset(lamp, 0),
      spacing: 17,
      offset: 2.05,
      side: "left",
      startInset: 8,
      endInset: 7,
      role: "structure",
      groupId: "street-lighting"
    });
  }

  function naturalClearance(p) {
    let clearance = 100;
    for (const item of occupied) clearance = Math.min(clearance, distance(p, item.p) - item.radius);
    for (const edge of chosen.edges) {
      clearance = Math.min(clearance, segmentDistance(p, nodes[edge[0]], nodes[edge[1]]) - 3.6);
    }
    for (const site of publicSites) {
      clearance = Math.min(clearance, segmentDistance(p, site.p, nodes[site.hub]) - 2.8);
    }
    return clearance;
  }

  const vegetation = api.sampleProbabilityField({
    bounds: { minX: -44, maxX: 44, minZ: -44, maxZ: 44 },
    maxPoints: 100,
    candidates: 1800,
    minDistance: 4.8,
    seed: api.seed,
    cluster: { strength: 0.65, scale: 14, seed: api.seed }
  }, function(sample) {
    const p = [sample.x, sample.z];
    if (naturalClearance(p) < 3.1) return 0;
    const edge = Math.max(Math.abs(sample.x), Math.abs(sample.z));
    return edge > 31 ? 0.85 : 0.25;
  });

  for (let i = 0; i < vegetation.length; i++) {
    const p = vegetation[i];
    const sample = api.environmentSample([p[0], p[1]]);
    const family = sample.height > 7 || i % 3 === 0 ? pine : tree;
    api.place({
      assetId: api.asset(family, i % 2),
      position: [p[0], p[1]],
      rotationY: api.random(0, api.TAU),
      scale: api.random(0.78, 1.15),
      groupId: "valley-woodland"
    });
  }

  const undergrowth = api.poissonDisk({
    bounds: { minX: -45, maxX: 45, minZ: -45, maxZ: 45 },
    minDistance: 3.5,
    maxPoints: 150,
    attempts: 24,
    seed: api.seed + 17
  });
  let rocksPlaced = 0;
  let shrubsPlaced = 0;
  for (let i = 0; i < undergrowth.length; i++) {
    const p = [undergrowth[i][0], undergrowth[i][1]];
    if (naturalClearance(p) < 1.8) continue;
    const isRock = i % 3 === 0;
    const index = isRock ? rocksPlaced : shrubsPlaced;
    api.place({
      assetId: api.asset(isRock ? rock : shrub, index % 2),
      position: p,
      rotationY: api.random(0, api.TAU),
      scale: api.random(0.65, 1.2),
      groupId: "valley-understory"
    });
    if (isRock) rocksPlaced++;
    else shrubsPlaced++;
  }

  api.spawn(nodes[9], rotate ? 0 : 90);
  api.renderSuggestion("建议在另行确认的渲染阶段使用清晰的山谷傍晚斜光，保留石屋墙体与屋顶层次、远近山坡空气透视和街巷可读性；灯光仅温暖地点亮公共院落及行走节点。主视角从入村道路上方斜看三处公共空间，再以地面步行视角检查连续街巷。");
}

function plan(api) {
  api.sceneIntent({kind:"authored",reason:"沿既有山谷地形组织密集石屋、公共院落与连续步行街巷，保留山坡自然背景。"});
  const orient = " Coordinate contract: Y+ is up, Z+ is the front/entrance/forward direction, X+ is right; place doors, facades, openings, windshields, or noses toward local Z+ and keep the model centered at its origin.";
  function asset(key,name,prompt,dimensions,variants) {
    return api.requireAsset({key:key,name:name,prompt:prompt+orient,dimensions:dimensions,variants:variants || 1,role:"structure"});
  }
  const home = asset("stone-home","山谷石屋","Standalone compact two-storey vernacular mountain dwelling, thick irregular fieldstone walls, weathered slate gable roof, chimney, recessed wooden entrance at ground level on front, small timber windows, attached shutters and modest flower boxes. Flat accessible entrance threshold, no external staircase, no ground or background.",[5.4,7.2,5.6],3);
  const hall = asset("village-hall","村民会堂","Standalone mountain village public hall, fieldstone masonry, broad slate roof, modest square bell turret, three front arches opening into a visible sheltered gathering porch, central accessible wooden door, joined facade ornaments, no lettering, no ground or background.",[11,10.5,8]);
  const bakery = asset("village-bakery","石砌烘焙坊","Standalone stone village bakery and communal oven house, slate roof, large chimney, open front serving hatch with visible bread shelves, side masonry oven incorporated into building, accessible front door, no text, ground or background.",[7,5.8,6]);
  const fountain = asset("village-fountain","石泉水池","Standalone low octagonal carved stone communal fountain, central short water spout and shallow basin, weathered stone coping, no surrounding ground, no background.",[3.2,2,3.2]);
  const stall = asset("market-stall","木棚摊位","Standalone compact rustic produce stall, timber trestles and striped faded linen canopy, baskets of vegetables and bread integrated on counter, front service opening, no lettering, ground or background.",[2.8,3,2.2],2);
  const bench = asset("village-bench","木石长凳","Standalone rustic wooden bench with heavy stone feet and timber backrest, sitting front faces Z+, no ground or background.",[2.4,1,0.7]);
  const supplies = asset("household-supplies","家用杂物","Standalone compact domestic storage arrangement of stacked split firewood, two wicker baskets and a ceramic jar, suitable beside a mountain village house wall, no ground or background.",[1.5,1.2,0.9],2);
  const trough = asset("wash-trough","公共洗衣槽","Standalone long fieldstone public wash trough, two washing slabs and timber bucket attached beside basin, no surrounding ground or background.",[3.4,1.1,1.4]);
  const lampKey = api.requireAsset({key:"village-lantern",name:"街巷灯柱",prompt:"Standalone wrought iron village lamp post with a single enclosed warm glass lantern, simple stone foot, no ground or background."+orient,dimensions:[0.5,3.4,0.5],role:"structure",light:{kind:"point",color:"#FFD59B",intensity:1.7,range:7,offset:[0,2.9,0]}});
  const treeKey = api.requireAsset({key:"valley-tree",name:"山谷乔木",prompt:"Standalone mature mountain deciduous tree, irregular airy branching crown, rugged trunk, natural varied foliage, no ground or background."+orient,dimensions:[6,10,6],variants:2,role:"environment"});
  const shrubKey = api.requireAsset({key:"valley-shrub",name:"山坡灌丛",prompt:"Standalone naturally irregular cluster of mountain shrubs and fern fronds, no ground or background."+orient,dimensions:[2.5,1.7,2.3],role:"environment"});
  const rockKey = api.requireAsset({key:"valley-rock",name:"山坡岩块",prompt:"Standalone weathered angular grey mountain rock outcrop with cracks and sparse moss in crevices, no ground or background."+orient,dimensions:[3.5,2.7,3],role:"environment"});

  const readings = [];
  for (let x=-32;x<=32;x+=8) {
    for (let z=-32;z<=32;z+=8) {
      const s=api.environmentSample([x,z]);
      readings.push({x:x,z:z,height:s.height,slope:s.slope,waterDistance:s.waterDistance});
    }
  }
  let best = null;
  for (const center of [[-6,-6],[6,-6],[-6,6],[6,6],[0,0]]) {
    for (const angle of [0,Math.PI/4,Math.PI/2,3*Math.PI/4]) {
      let score=0;
      const c=Math.cos(angle),s=Math.sin(angle);
      for (const uv of [[0,0],[0,-26],[0,26],[-17,-18],[17,-18],[-17,18],[17,18],[-7,0],[7,0]]) {
        const p=[center[0]+uv[0]*c-uv[1]*s,center[1]+uv[0]*s+uv[1]*c];
        const sample=api.environmentSample(p);
        score+=sample.slope*5+sample.height*0.25;
        if (sample.waterDistance<2) score+=200;
      }
      if (best===null || score<best.score) best={center:center,angle:angle,score:score};
    }
  }
  const cs=Math.cos(best.angle),sn=Math.sin(best.angle);
  function world(u,v) {
    return [best.center[0]+u*cs-v*sn,best.center[1]+u*sn+v*cs];
  }
  function ground(u,v) { return api.environmentSample(world(u,v)); }
  function setPad(u,v,radius) {
    const p=world(u,v),s=api.environmentSample(p);
    api.sculptTerrain({mode:"flatten",point:p,radius:radius,strength:0.95,targetHeight:s.height});
    return api.environmentSample(p).height;
  }
  function path(id,local,width) {
    const pts=[];
    for (const p of local) pts.push(world(p[0],p[1]));
    for (let i=0;i<pts.length-1;i++) {
      api.rampTerrain({start:pts[i],end:pts[i+1],width:width+0.8,softness:1.6,strength:1});
    }
    for (const p of pts) api.environmentSample(p);
    return api.route({id:id,points:pts,width:width,curve:"polyline",surface:"paving",material:"cobblestone"});
  }
  function put(key,variant,u,v,target,group) {
    return api.place({assetId:api.asset(key,variant),position:world(u,v),facing:{target:world(target[0],target[1])},groupId:group});
  }

  setPad(0,0,8.8);
  api.surface({id:"central-square",surface:"paving",material:"garden-stone",region:{kind:"circle",center:world(0,0),radius:8.4},clearNatural:true});
  setPad(0,-13,6.6);
  setPad(13,0,4.7);
  setPad(-13,0,4.4);
  const buildings=[];
  let index=0;
  for (const side of [-1,1]) {
    for (const v of [-25,-17,-9,9,17,25]) {
      const innerU=side*(6.4+(index%2)*0.35);
      const outerU=side*(19.3+(index%3)*0.3);
      for (const u of [innerU,outerU]) {
        const laneU=side*12.7;
        const candidate=ground(u,v);
        let localV=v;
        let chosen=candidate.slope*3+(candidate.waterDistance<2?100:0);
        for (const delta of [-1.1,1.1]) {
          const ss=ground(u,v+delta);
          const cost=ss.slope*3+(ss.waterDistance<2?100:0);
          if (cost<chosen) {chosen=cost;localV=v+delta;}
        }
        const corners=[[-2.7,-2.8],[2.7,-2.8],[-2.7,2.8],[2.7,2.8]];
        let minH=100,maxH=-100;
        for (const corner of corners) {
          const ss=ground(u+corner[0],localV+corner[1]);
          minH=Math.min(minH,ss.height);
          maxH=Math.max(maxH,ss.height);
        }
        setPad(u,localV,4.1);
        buildings.push({u:u,v:localV,lane:laneU,index:index,relief:maxH-minH});
        index++;
      }
    }
  }

