  const rock=api.requireAsset({key:"valley-rocks",name:"山岩",role:"environment",variants:2,dimensions:[3.5,2.5,2.8],prompt:"Standalone naturally weathered angular mountain rock outcrop with layered stone fractures, irregular silhouette, no ground or background."+orientation});

  api.surface({id:"central-square",surface:"paving",material:"garden-stone",region:{kind:"circle",center:village.plaza,radius:6.5},clearNatural:true});
  api.sculptTerrain({mode:"flatten",point:village.plaza,radius:7.2,targetHeight:datum,strength:1});
  function road(id,points,width) {
    for (let i=0;i<points.length-1;i++) {
      const a=points[i],b=points[i+1];
      api.rampTerrain({start:a,end:b,width:width+1.4,startHeight:grade(a),endHeight:grade(b),softness:0.8,strength:1});
    }
    return api.route({id:id,name:id,points:points,curve:"polyline",width:width,surface:"paving",material:"cobblestone",groupId:"village"});
  }
  const routes=[];
  for (let i=0;i<village.routes.length;i++) routes.push(road("village-street-"+i,village.routes[i],i<2?3.4:2.7));
  for (let i=0;i<village.extra.length;i++) road("public-link-"+i,village.extra[i],2.3);

  function building(key,variant,h,w,d,group) {
    const p=[h[0],h[1]],target=[h[2],h[3]];
    const len=distance(p,target);
    const dx=(target[0]-p[0])/Math.max(0.001,len),dz=(target[1]-p[1])/Math.max(0.001,len);
    const door=[p[0]+dx*d/2,p[1]+dz*d/2];
    const level=grade(door);
    api.sculptTerrain({mode:"flatten",point:p,radius:Math.sqrt(w*w+d*d)/2+0.45,targetHeight:level,strength:1});
    const ref=api.place({assetId:api.asset(key,variant),position:[p[0],level,p[1]],facing:{target:target},groupId:group});
    api.foundation({name:"随地形石基",under:[ref],shape:"rounded-rectangle",margin:0.12,top:"level",thickness:0.12,maxThickness:3.2,material:"stone"});
    api.rampTerrain({start:door,end:target,width:2,startHeight:level,endHeight:grade(target),softness:0.5,strength:1});
    api.route({id:group+"-door",points:[door,target],width:1.5,surface:"paving",material:"cobblestone",groupId:group});
    const side=[dz,-dx];
    const stoop=[door[0]+dx*0.75,door[1]+dz*0.75];
    for (const sign of [-1,1]) {
      const item=[stoop[0]+side[0]*sign*(w/2-0.55),stoop[1]+side[1]*sign*(w/2-0.55)];
      api.place({assetId:api.asset(supplies,sign===1?0:1),position:item,facing:{target:target},groupId:group});
    }
    return {p:p,door:door,target:target,side:side,forward:[dx,dz]};
  }
  for (let i=0;i<village.houses.length;i++) {
    const h=village.houses[i];
    const g="home-"+i;
    const b=building(house,i%3,h,5.6,6,g);
    if (i%2===0) {
      api.place({assetId:api.asset(wood,0),position:[b.p[0]+b.side[0]*3.55,b.p[1]+b.side[1]*3.55],facing:{target:b.target},groupId:g});
    }
    if (i%4===0) {
      const a=[b.p[0]-b.forward[0]*3.6-b.side[0]*2.8,b.p[1]-b.forward[1]*3.6-b.side[1]*2.8];
      const e=[b.p[0]-b.forward[0]*3.6+b.side[0]*2.8,b.p[1]-b.forward[1]*3.6+b.side[1]*2.8];
      const bays=api.subdividePathBySpan({points:[a,e],span:2.8,fit:"stretch"});
      for (const bay of bays) api.placeBetween({assetId:api.asset(wall,0),start:bay.start,end:bay.end,spanAxis:"x",dimensions:[3,1.4,0.6],groupId:g});
    }
  }
  const publicKeys=[hall,bakery,workshop];
  for (let i=0;i<3;i++) {
    const b=building(publicKeys[i],0,village.public[i],i===0?9:7,i===0?7:6,"public-"+i);
    for (const sign of [-1,1]) {
      const p=[b.door[0]+b.forward[0]*1.1+b.side[0]*sign*2.5,b.door[1]+b.forward[1]*1.1+b.side[1]*sign*2.5];
      api.place({assetId:api.asset(i===0?bench:wood,0),position:p,facing:{target:b.target},groupId:"public-"+i});
    }
  }

  api.place({assetId:api.asset(fountain,0),position:[0,3.8],groupId:"square"});
  for (const x of [-5,5]) {
    api.place({assetId:api.asset(bench,0),position:[x,2.9],facing:{target:[0,2.9]},groupId:"square"});
    api.place({assetId:api.asset(lamp,0),position:[x,-2.7],groupId:"square"});
  }
  for (let i=0;i<4;i++) {
    const p=index===0?[i%2===0?-4.5:4.5,26+Math.floor(i/2)*4]:[i%2===0?-3.9:3.9,10+Math.floor(i/2)*5];
    api.place({assetId:api.asset(stall,i%2),position:p,facing:{target:[0,p[1]]},groupId:"market"});
  }
  for (let i=0;i<routes.length;i++) {
    api.placeAlongRoute({routeId:routes[i],assetId:api.asset(lamp,0),spacing:16,offset:2.2,side:"left",startInset:5,endInset:5,groupId:"street-furniture"});
  }

  api.grass({id:"valley-meadow",preset:"meadow",region:{kind:"polygon",points:[[-47,-47],[47,-47],[47,47],[-47,47]]},density:0.48,variation:0.7,height:0.32,mix:{short:0.65,tall:0.3,flowers:0.05}});
  const nature=api.poissonDisk({bounds:{minX:-44,maxX:44,minZ:-44,maxZ:44},minDistance:5,maxPoints:150,seed:api.seed});
  let trees=0,rocks=0;
  for (const p of nature) {
    let clear=distance(p,village.plaza)>11;
    for (const h of village.houses) if (distance(p,[h[0],h[1]])<7) clear=false;
    for (const h of village.public) if (distance(p,[h[0],h[1]])<8) clear=false;
    const s=api.environmentSample(p,{guideIds:routes});
    if (s.guideDistance<5.5) clear=false;
    if (clear) {
      if (s.slope<32 && trees<45) {
        api.place({assetId:api.asset(tree,trees%2),position:[p[0],p[1]],rotationY:api.random(0,api.TAU),scale:api.random(0.8,1.18),groupId:"valley-nature"});
        trees++;
      } else if (rocks<22) {
        api.place({assetId:api.asset(rock,rocks%2),position:[p[0],p[1]],rotationY:api.random(0,api.TAU),scale:api.random(0.75,1.35),groupId:"valley-nature"});
        rocks++;
      }
    }
  }
  // 远景岩石和谷口树保证两种自然形态均可见，并框出村庄游览视线。
  for (let i=0;i<2;i++) {
    api.place({assetId:api.asset(rock,i),position:[i===0?-43:43,-41],groupId:"valley-nature"});
    api.place({assetId:api.asset(tree,i),position:[i===0?-40:40,40],groupId:"valley-nature"});
  }
  api.spawn(village.entry,180);
  api.renderSuggestion("建议从谷口低机位及山坡斜俯视检查：层叠石屋、石板屋顶、沿坡街巷、会堂钟楼和留白广场都应清晰可读。后续渲染可采用柔和傍晚日光与少量暖油灯，保留山谷植被和石材质感；当前阶段不更改曝光。");
}

function plan(api) {
  api.sceneIntent({kind:"authored",reason:"依山谷原有地势组织密集石屋、连续街巷和村民公共生活空间。"});
  const orientation = " Coordinate contract: Y+ is up, Z+ is the front/entrance/forward direction, X+ is right; place doors, facades, openings, windshields, or noses toward local Z+ and keep the model centered at its origin.";
  function asset(key,name,prompt,dimensions,variants) {
    api.requireAsset({key:key,name:name,prompt:prompt+orientation,dimensions:dimensions,variants:variants,role:"structure"});
  }
  asset("house","山谷石屋","Standalone compact inhabited mountain village house, thick irregular stone masonry, two uneven storeys, dark slate pitched roof, timber lintels, chimney, recessed front entrance at ground level, small shuttered windows, attached shallow front doorstep and firewood niche. No ground or background.",[7,8,7],3);
  asset("hall","村民会堂","Standalone mountain village communal hall, substantial stone masonry, tall slate roof, modest square bell turret, timber double entrance on front, shallow entrance steps, arched front windows, attached carved stone ornament, rustic inhabited character. No ground, text or background.",[13,12,10],1);
  asset("bakery","村庄烘坊","Standalone small communal mountain bakery, rough stone walls, slate roof, broad ground-level front doorway, visible bread oven through open front, chimney, attached timber serving counter and baskets of bread. No ground, text or background.",[9,6,7],1);
  asset("shelter","集市棚","Standalone reusable mountain market stall, timber posts, slate pitched canopy, stone counter displaying baskets of vegetables and pottery, front open toward Z+, no ground, text or background.",[3.6,3.8,2.6],2);
  asset("fountain","石泉水槽","Standalone village communal stone fountain, upright carved waterspout feeding an elongated shallow stone trough containing water, realistic worn edges, no surrounding ground or background.",[4.8,2.3,2.2],1);
  asset("bench","木石长凳","Standalone rustic mountain village bench with stone legs and heavy timber seat and backrest, no ground or background.",[2.4,1.1,0.7],1);
  asset("domestic","门前生活杂物","Standalone compact domestic arrangement of neatly stacked firewood, a clay planter and woven basket beside a low timber chopping block, no ground or background.",[1.7,1.2,1.1],2);
  asset("cart","村庄手推车","Standalone small two-wheel timber handcart carrying flour sacks and tied firewood, handles toward local Z+, no ground or background.",[1.5,1.5,2.7],1);
  asset("wall","毛石挡墙","Standalone compatible retaining wall bay of irregular mountain stone masonry with coping, canonical span along local X, 3m long, 1.4m high, 0.65m thick. Flat joining ends, no ground or background.",[3,1.4,0.65],1);
  api.requireAsset({key:"lamp",name:"街巷灯",role:"structure",dimensions:[0.65,3.2,0.65],light:{kind:"point",color:"#FFD39B",intensity:1.6,range:6,offset:[0,2.7,0]},prompt:"Standalone rustic wrought iron village lamp post with a single sheltered glass lantern, no ground or background."+orientation});
  api.requireAsset({key:"tree",name:"山谷乔木",role:"environment",variants:2,dimensions:[5,10,5],prompt:"Standalone mountain valley deciduous tree, irregular branching, airy natural crown, visible trunk, no ground or background."+orientation});
  api.requireAsset({key:"rock",name:"山谷露岩",role:"environment",dimensions:[4,2.6,3],prompt:"Standalone weathered angular mountain rock outcrop, fractured natural stone, no ground or background."+orientation});

  // 两个连接拓扑不同的有界候选：纵向主街与梯形横街。
  const candidates = [
    {
      name:"谷底主街与两侧巷环",
      roads:[
        [[0,-43],[0,-22],[0,0],[0,22],[0,27]],
        [[-20,-22],[-20,0],[-20,22]],
        [[20,-22],[20,0],[20,22]],
        [[-20,-22],[0,-22],[20,-22]],
        [[-20,0],[0,0],[20,0]],
        [[-20,22],[0,22],[20,22]]
      ],
      homes:[],
      hall:[0,36], plaza:[0,26], bakery:[-13,30], bakeryAccess:[-13,22]
    },
    {
      name:"沿坡横街与双侧联络巷",
      roads:[
        [[-42,-20],[-30,-20],[0,-20],[30,-20]],
        [[-30,0],[0,0],[30,0]],
        [[-30,20],[0,20],[30,20]],
        [[-30,-20],[-30,0],[-30,20]],
        [[30,-20],[30,0],[30,20]],
        [[0,20],[0,27]]
      ],
      homes:[],
      hall:[0,36], plaza:[0,26], bakery:[-14,29], bakeryAccess:[-14,20]
    }
  ];
  for (const x of [-30,-10,10,30]) {
    for (const z of [-15,-5,7,16]) {
      let streetX = 0;
      if (x === -30) streetX = -20;
      if (x === 30) streetX = 20;
      candidates[0].homes.push({p:[x,z],access:[streetX,z]});
    }
  }
  for (const z of [-30,-10,10]) {
    for (const x of [-22,-11,0,11,22]) {
      const streetZ = z === -30 ? -20 : z === -10 ? 0 : 20;
      candidates[1].homes.push({p:[x,z],access:[x,streetZ]});
    }
  }
  function sampleFootprint(p,w,d) {
    let low = 1000;
    let high = -1000;
    let slope = 0;
    for (const dx of [-w/2,0,w/2]) {
      for (const dz of [-d/2,0,d/2]) {
        const s = api.environmentSample([p[0]+dx,p[1]+dz]);
        low = Math.min(low,s.height);
        high = Math.max(high,s.height);
        slope = Math.max(slope,s.slope);
      }
    }
    return {relief:high-low,height:api.environmentSample(p).height,slope:slope};
  }
  for (const c of candidates) {
    c.maxGrade = 0;
    c.maxRelief = 0;
    c.steepFootprint = false;
    for (const road of c.roads) {
      for (let i=0;i<road.length-1;i++) {
        const a=road[i], b=road[i+1];
        const length=Math.sqrt((b[0]-a[0])*(b[0]-a[0])+(b[1]-a[1])*(b[1]-a[1]));
        let previous=api.environmentSample(a);
        const steps=Math.max(1,Math.ceil(length/4));
        for (let j=1;j<=steps;j++) {
          const p=[a[0]+(b[0]-a[0])*j/steps,a[1]+(b[1]-a[1])*j/steps];
          const s=api.environmentSample(p);
          c.maxGrade=Math.max(c.maxGrade,Math.abs(s.height-previous.height)/(length/steps));
          previous=s;
        }
      }
    }
    for (const home of c.homes) {
      const f=sampleFootprint(home.p,7,7);
      c.maxRelief=Math.max(c.maxRelief,f.relief);
      if (f.slope>0.65) c.steepFootprint=true;
      const a=api.environmentSample(home.access);
      const dx=home.p[0]-home.access[0], dz=home.p[1]-home.access[1];
      c.maxGrade=Math.max(c.maxGrade,Math.abs(f.height-a.height)/Math.max(1,Math.sqrt(dx*dx+dz*dz)));
    }
    c.maxRelief=Math.max(c.maxRelief,sampleFootprint(c.hall,13,10).relief,sampleFootprint(c.bakery,9,7).relief);
    c.viable=c.maxGrade<=0.22 && c.maxRelief<=2.5 && !c.steepFootprint;
  }
  let chosen=candidates[0];
  if (!chosen.viable && candidates[1].viable) chosen=candidates[1];
  else if (!chosen.viable && !candidates[1].viable) {
    // 无天然低坡候选时，先排除大开挖地基，再以最大步行坡度决定局部整坡。
    if (chosen.maxRelief>3.5 && candidates[1].maxRelief<=3.5) chosen=candidates[1];
    else if ((chosen.maxRelief>3.5)===(candidates[1].maxRelief>3.5) && candidates[1].maxGrade<chosen.maxGrade) chosen=candidates[1];
