function plan(api) {
  api.sceneIntent({kind:"authored",reason:"保留雪山基底，以实测坡度、入口高差和步行距离选择石屋村落组团与路网。"});
  const orient = " Coordinate contract: Y+ is up, Z+ is the front/entrance/forward direction, X+ is right; place doors, facades, openings, windshields, or noses toward local Z+ and keep the model centered at its origin.";
  function sample(p) {
    return api.environmentSample(p);
  }
  function distance(a,b) {
    const dx=a[0]-b[0], dz=a[1]-b[1];
    return Math.sqrt(dx*dx+dz*dz);
  }
  function asset(key,name,prompt,dimensions,extra) {
    const spec={key:key,name:name,prompt:prompt+orient,dimensions:dimensions,role:"structure"};
    if (extra) spec.light=extra;
    api.requireAsset(spec);
    return api.asset(key,0);
  }
  function footprint(p,w,d) {
    const mid=sample(p);
    let lo=mid.height, hi=mid.height, slope=0;
    for (const dx of [-w/2,0,w/2]) {
      for (const dz of [-d/2,0,d/2]) {
        const s=sample([p[0]+dx,p[1]+dz]);
        lo=Math.min(lo,s.height);
        hi=Math.max(hi,s.height);
        slope+=Math.abs(s.slope);
      }
    }
    return {height:mid.height,relief:hi-lo,slope:slope/9};
  }
  // 两种拓扑同时检查：南、东入口的公共中心辐射网；西、北入口的串联村巷。
  const alternatives=[
    {centers:[[-24,-20],[23,-14],[0,23]],edges:[[0,1],[0,2]],entries:[{p:[-35,-44],to:0},{p:[44,-4],to:1}]},
    {centers:[[-25,16],[20,23],[3,-23]],edges:[[0,1],[1,2]],entries:[{p:[-44,27],to:0},{p:[29,44],to:1}]}
  ];
  const offsets=[[-12,0],[12,0],[0,12],[0,-12]];
  function cluster(center) {
    const plaza=footprint(center,11,11);
    const buildings=[];
    let cost=plaza.relief*9+plaza.slope*0.15;
    for (let j=0;j<offsets.length;j++) {
      const off=offsets[j];
      let best=null;
      // 沿同一入口方向微调选址，避免任意旋转造成门口与路不相接。
      for (const shift of [-2,0,2]) {
        const p=[center[0]+off[0]+(off[0]===0?shift:0),center[1]+off[1]+(off[1]===0?shift:0)];
        const f=footprint(p,7,7);
        const delta=Math.abs(f.height-plaza.height);
        const score=f.relief*7+f.slope*0.12+delta*5+Math.max(0,delta-1.6)*30;
        if (!best || score<best.cost) best={p:p,height:f.height,cost:score,relief:f.relief};
      }
      buildings.push(best);
      cost+=best.cost;
    }
    return {center:center,height:plaza.height,buildings:buildings,cost:cost};
  }
  function gateway(center,target) {
    const sx=target[0]>=center[0]?1:-1;
    const sz=target[1]>=center[1]?1:-1;
    return [center[0]+sx*8,center[1]+sz*8];
  }
  function makeConnection(a,b,aCluster,bCluster) {
    const points=[a];
    if (aCluster) points.push(gateway(a,b));
    if (bCluster) points.push(gateway(b,a));
    points.push(b);
    return points;
  }
  function roadCost(points,groups) {
    let result=0;
    for (let i=0;i<points.length-1;i++) {
      const a=points[i], b=points[i+1], length=distance(a,b);
      const sa=sample(a), sb=sample(b);
      const grade=Math.abs(sa.height-sb.height)/Math.max(1,length);
      result+=length*0.2+Math.max(0,grade-0.16)*length*35;
      for (let k=0;k<=8;k++) {
        const t=k/8;
        const p=[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];
        const s=sample(p);
        const target=sa.height+(sb.height-sa.height)*t;
        result+=Math.abs(s.height-target)*2+Math.abs(s.slope)*0.05;
        for (const g of groups) {
          for (const house of g.buildings) {
            if (distance(p,house.p)<5.4) result+=150;
          }
        }
      }
    }
    return result;
  }
  let chosen=null;
  for (const candidate of alternatives) {
    const groups=[];
    let score=0;
    for (const c of candidate.centers) {
      const g=cluster(c);
      groups.push(g);
      score+=g.cost;
    }
    const roads=[];
    for (const edge of candidate.edges) {
      roads.push(makeConnection(candidate.centers[edge[0]],candidate.centers[edge[1]],true,true));
    }
    for (const entry of candidate.entries) {
      roads.push(makeConnection(entry.p,candidate.centers[entry.to],false,true));
    }
    for (const road of roads) score+=roadCost(road,groups);
    candidate.groups=groups;
    candidate.roads=roads;
    candidate.score=score;
    if (!chosen || score<chosen.score) chosen=candidate;
  }

  const cottage=asset("snow-stone-home","雪顶石屋",
    "Standalone compact inhabited alpine stone cottage, thick rough stone walls, steep slate roof carrying patchy accumulated snow, chimney, wooden shutters, recessed front door centered on Z+ facade at base level, small windows, attached wood bin and simple unlettered house plaque. Grounded vernacular architecture, no terrain or background.",[7,6.8,6]);
  const hall=asset("village-hall","村民会堂",
    "Standalone small mountain village communal stone hall, steep snow laden slate roof, squat chimney, broad timber double entrance centered on front Z+ at base level, attached notice board without lettering, narrow windows and carved wooden lintel. No ground or background.",[7,7.5,6]);
  const bakery=asset("village-bakery","面包作坊",
    "Standalone alpine stone communal bakehouse, steep snowy slate roof, masonry oven chimney, front timber door at base level, front serving opening with visible bread shelves, attached blank hanging bread-shaped sign, no lettering, no ground or background.",[7,6,6]);
  const refuge=asset("walker-refuge","登山驿舍",
    "Standalone alpine walkers refuge built of stone and heavy timber, steep snow capped slate roof, front entrance at base level, attached shallow porch within building footprint, integrated boot shelves and roofed pack hooks on the front facade, no text, no ground or background.",[7,6.5,6]);
  const bench=asset("timber-bench","厚木长凳",
    "Standalone sturdy alpine outdoor bench, thick weathered timber seat and back on stone feet, seating faces Z+, slight snow on backrest only, no ground or background.",[2.1,1,0.7]);
  const trough=asset("stone-trough","石砌水槽",
    "Standalone village stone drinking trough with a timber spout and a small contained still water surface inside the basin, winter frost around rim, no flowing stream, no ground or background.",[2.4,1.1,1.2]);
  const wood=asset("firewood-rack","柴薪架",
    "Standalone compact roofed firewood storage rack, orderly split logs under a steep little snow capped timber roof, front opening toward Z+, no ground or background.",[2.4,2.2,1.2]);
  const supplies=asset("supply-sledge","运货雪橇",
    "Standalone stationary hand drawn alpine wooden cargo sledge carrying tied sacks and a small crate, runners and towing handle, forward handle toward Z+, no ground, no text or background.",[1.4,1,2.5]);
  const marker=asset("trail-marker","步道指示牌",
    "Standalone mountain village timber trail signpost with two carved arrow boards bearing simple walking and house pictograms, no letters or words, small snow cap, no ground or background.",[1.2,2.3,0.35]);
  const lamp=asset("village-lantern","石径路灯",
    "Standalone low sturdy wrought iron village lantern post on a small stone foot, enclosed warm glass lantern with protective peaked cap, no ground or background.",[0.5,2.7,0.5],
    {kind:"point",color:"#FFD6A0",intensity:1.8,range:7,offset:[0,2.25,0]});
  const tree=asset("alpine-pine","高山雪松",
    "Standalone windswept high altitude conifer with sparse branches carrying irregular snow clumps, visible trunk, no ground or background.",[4,8,4]);
  const rail=asset("path-railing","步道护栏",
    "Standalone compatible alpine timber safety railing module, two posts joined by two horizontal rails, connection span along local X, canonical width 2 metres, height 1 metre, depth 0.18 metres, no ground or background.",[2,1,0.18]);

  function limited(h) {return Math.max(0,Math.min(15.3,h));}
  for (let gIndex=0;gIndex<chosen.groups.length;gIndex++) {
    const g=chosen.groups[gIndex], c=g.center;
    g.height=limited(g.height);
    api.sculptTerrain({mode:"flatten",point:c,radius:6.7,targetHeight:g.height,strength:1});
    api.surface({id:"square-"+gIndex,surface:"paving",material:"garden-stone",region:{kind:"circle",center:c,radius:6},clearNatural:true});
    for (let j=0;j<g.buildings.length;j++) {
      const b=g.buildings[j];
      b.height=limited(b.height);
      api.sculptTerrain({mode:"flatten",point:b.p,radius:5,targetHeight:b.height,strength:1});
    }
  }

  function walk(points,id,width,group) {
    const heights=[];
    for (const p of points) heights.push(sample(p).height);
    for (let i=0;i<points.length-1;i++) {
      const a=points[i],b=points[i+1];
      const len=distance(a,b);
      const difference=Math.abs(heights[i+1]-heights[i]);
      if (difference/Math.max(1,len)>0.18) {
        api.foundation({name:"缓级石阶 "+id,shape:"path",points:[a,b],width:width,top:"steps",stepHeight:0.15,thickness:0.12,maxThickness:1.2,material:"stone"});
      } else {
        api.rampTerrain({start:a,end:b,width:width+1,startHeight:heights[i],endHeight:heights[i+1],strength:1,softness:0.65});
      }
    }
    return api.route({id:id,name:"可步行石巷",points:points,curve:"polyline",width:width,surface:"paving",material:"garden-stone",groupId:group});
  }
  for (let r=0;r<chosen.roads.length;r++) {
    walk(chosen.roads[r],"village-path-"+r,2.6,"village-circulation");
  }

  const publicAssets=[hall,bakery,refuge];
  for (let gIndex=0;gIndex<chosen.groups.length;gIndex++) {
    const g=chosen.groups[gIndex], c=g.center, group="quarter-"+gIndex;
    for (let j=0;j<g.buildings.length;j++) {
      const b=g.buildings[j];
      const dx=c[0]-b.p[0], dz=c[1]-b.p[1];
      const len=Math.max(1,distance(c,b.p));
      const ux=dx/len, uz=dz/len;
      const door=[b.p[0]+ux*3,b.p[1]+uz*3];
      const apron=[b.p[0]+ux*4.1,b.p[1]+uz*4.1];
      const start=[c[0]-ux*4.4,c[1]-uz*4.4];
      const building=api.place({assetId:j===3?publicAssets[gIndex]:cottage,name:j===3?["会堂","公共烤坊","登山驿舍"][gIndex]:"山地石屋",position:[b.p[0],b.height+0.18,b.p[1]],facing:{target:c},groupId:group});
