      walk([start,apron],"door-path-"+gIndex+"-"+j,1.8,group);
      api.foundation({name:"门前低石阶",shape:"path",points:[apron,door],width:1.9,top:"steps",stepHeight:0.15,thickness:0.18,maxThickness:0.7,material:"stone"});
      const side=[b.p[0]+uz*4.1+ux*1.1,b.p[1]-ux*4.1+uz*1.1];
      api.place({assetId:wood,position:side,facing:{target:c},groupId:group});
      api.place({assetId:bench,position:[c[0]-ux*5+uz*1.7,c[1]-uz*5-ux*1.7],facing:{target:c},groupId:group});
      if (j===3) {
        api.place({assetId:supplies,position:[b.p[0]-uz*4.1+ux*1.5,b.p[1]+ux*4.1+uz*1.5],facing:{target:c},groupId:group});
      }
    }
    api.place({assetId:trough,position:[c[0]+1.8,c[1]+1.4],facing:{target:[c[0],c[1]-3]},groupId:group});
    api.place({assetId:marker,position:[c[0]-2.6,c[1]+2.7],facing:{target:c},groupId:group});
    for (const p of [[c[0]-4.6,c[1]-3],[c[0]+4.6,c[1]+3]]) {
      api.place({assetId:lamp,position:p,groupId:group});
    }
  }

  // 只在有明显下落风险的一侧安装护栏，保留普通村巷的开放边缘。
  for (let r=0;r<chosen.roads.length;r++) {
    const pts=chosen.roads[r];
    for (let i=0;i<pts.length-1;i++) {
      const a=pts[i], b=pts[i+1], len=distance(a,b);
      if (len<10) continue;
      const nx=-(b[1]-a[1])/len, nz=(b[0]-a[0])/len;
      const bays=api.subdividePathBySpan({points:[a,b],span:2.5,startInset:3,endInset:3,fit:"center"});
      for (const bay of bays) {
        for (const side of [-1,1]) {
          const p=[bay.center[0]+nx*side*3,bay.center[1]+nz*side*3];
          if (sample(bay.center).height-sample(p).height>1.1) {
            const start=[bay.start[0]+nx*side*1.6,bay.start[1]+nz*side*1.6];
            const end=[bay.end[0]+nx*side*1.6,bay.end[1]+nz*side*1.6];
            api.placeBetween({assetId:rail,start:start,end:end,dimensions:[2,1,0.18],spanAxis:"x",groupId:"village-circulation"});
          }
        }
      }
    }
  }
  // 雪山植被保留稀疏分布，不用树木填满广场或遮住入口。
  const naturalPoints=api.poissonDisk({bounds:{minX:-43,maxX:43,minZ:-42,maxZ:42},minDistance:7,maxPoints:70,seed:api.seed});
  let planted=0;
  for (const p of naturalPoints) {
    let clear=true;
    for (const g of chosen.groups) {
      if (distance(p,g.center)<20) clear=false;
    }
    for (const road of chosen.roads) {
      for (let i=0;i<road.length-1;i++) {
        const a=road[i],b=road[i+1];
        const dx=b[0]-a[0],dz=b[1]-a[1],den=dx*dx+dz*dz;
        const t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dz)/Math.max(1,den)));
        if (distance(p,[a[0]+dx*t,a[1]+dz*t])<4.5) clear=false;
      }
    }
    const s=sample(p);
    if (clear && planted<18 && s.slope<40) {
      api.place({assetId:tree,position:[p[0],p[1]],scale:0.8+0.3*((planted%4)/3),rotationY:planted*2.399,role:"environment"});
      planted++;
    }
  }
  if (planted===0) {
    const p=[-43,-40];
    sample(p);
    api.place({assetId:tree,position:p,role:"environment"});
  }
  const entry=chosen.entries[0].p;
  api.spawn(entry,0);
  for (const g of chosen.groups) {
    sample(g.center);
    sample([g.center[0]-6,g.center[1]-6]);
  }
  api.renderSuggestion("雪山石屋村：保留现有起伏山形和自然地形遮挡，积雪与裸露石径并存。建议柔和冬日下午光，石屋烟囱、厚石台基及村巷台阶清晰可读；从主入口人眼高度检查通路，再以斜俯视展现三个不同标高的组团。灯笼仅提供局部暖光，最终曝光与雪材质在确认渲染阶段设置。");
}

