  const bench = asset("village-bench","木长椅","Standalone robust alpine timber bench on stone legs, seat faces Z+, lightly snow dusted backrest, no ground or background.",[2.2,1,0.7]);
  const wood = asset("firewood","柴薪架","Standalone narrow stacked firewood rack with timber supports and small snow capped pitched cover, accessible front Z+, no ground or background.",[2.2,1.8,0.9]);
  const steps = asset("stone-stair","山路石阶","Standalone straight flight of eight evenly spaced rough stone pedestrian steps, 2.4m wide, total rise 1.2m over 4m run, ascending toward local Z+, continuous timber handrails on both sides, bottom tread at local front-negative end, no ground or background.",[2.4,1.2,4]);
